            if circuit[i][j] == 1:
                adjacency_matrix[i][j] = 1
                adjacency_matrix[j][i] = 1

    # Perform Gaussian elimination to get the reduced row echelon form
    reduced_matrix = gaussian_elimination(adjacency_matrix)

